package com.yeeyuan;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import jakarta.servlet.http.*;
import org.springframework.stereotype.Service;
import org.springframework.http.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestClient;
import static com.yeeyuan.Db.*;
@Service
public class Auth {
 public record User(UUID id,String kind,Set<String> roles){}
 final Db db;final Settings config; final Crypto crypto;final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder(12);
 public Auth(Db db,Settings config,Crypto crypto){this.db=db;this.config=config;this.crypto=crypto;}
 public String encodePassword(String value){return passwords.encode(value);}
 public boolean matchesPassword(String value,String hash){return passwords.matches(value,hash);}
 String cookieName(){return config.secureCookies()?"__Host-session":"yy-local-session";}
 Map<String,Object> session(HttpServletRequest req){if(req.getCookies()==null)return null;for(var c:req.getCookies())if(c.getName().equals(cookieName())){var rows=db.jdbc.queryForList("SELECT * FROM auth_session WHERE token_hash=? AND expires_at>now() AND absolute_expires_at>now()",Crypto.hash(c.getValue()));if(!rows.isEmpty())return rows.get(0);}return null;}
 public User user(HttpServletRequest req){var s=session(req);if(s==null||s.get("user_id")==null)throw new Problem(401,"LOGIN_REQUIRED","กรุณาเริ่มต้นใช้งานหรือเข้าสู่ระบบใหม่");UUID id=uuid(s,"user_id");var u=db.one("SELECT * FROM app_user WHERE id=? AND active=true",id);Set<String> roles=new HashSet<>(db.jdbc.queryForList("SELECT role FROM staff_role WHERE user_id=?",String.class,id));return new User(id,str(u,"kind"),roles);}
 public User staff(HttpServletRequest req){User u=user(req);if(!u.kind.equals("STAFF"))throw new Problem(403,"FORBIDDEN","เฉพาะพนักงานที่ได้รับสิทธิ์");return u;}
 public User manager(HttpServletRequest req){User u=staff(req);if(Collections.disjoint(u.roles,Set.of("OWNER","MANAGER")))throw new Problem(403,"FORBIDDEN","เฉพาะผู้จัดการร้าน");return u;}
 public User cashier(HttpServletRequest req){User u=staff(req);if(Collections.disjoint(u.roles,Set.of("OWNER","MANAGER","CASHIER")))throw new Problem(403,"FORBIDDEN","เฉพาะพนักงานรับออเดอร์");return u;}
 public User kitchen(HttpServletRequest req){User u=staff(req);if(Collections.disjoint(u.roles,Set.of("OWNER","MANAGER","KITCHEN")))throw new Problem(403,"FORBIDDEN","เฉพาะพนักงานครัว");return u;}
 public void csrfCheck(HttpServletRequest req){var s=session(req);String v=req.getHeader("X-CSRF-Token");if(s==null||v==null||!Crypto.equal(str(s,"csrf_hash"),Crypto.hash(v)))throw new Problem(403,"CSRF_INVALID","เซสชันเปลี่ยนแล้ว กรุณาโหลดหน้าใหม่");}
 @Transactional public Map<String,Object> csrf(HttpServletRequest req,HttpServletResponse res){var old=session(req);String token=Crypto.token();if(old==null){create(null,token,res,Duration.ofHours(1));}else{db.jdbc.update("UPDATE auth_session SET csrf_hash=? WHERE id=?",Crypto.hash(token),uuid(old,"id"));}return Map.of("csrfToken",token);}
 void create(UUID user,String csrf,HttpServletResponse res,Duration duration){String token=Crypto.token();db.jdbc.update("INSERT INTO auth_session(user_id,token_hash,csrf_hash,expires_at,absolute_expires_at) VALUES(?,?,?,?,?)",user,Crypto.hash(token),Crypto.hash(csrf),Timestamp.from(Instant.now().plus(duration)),Timestamp.from(Instant.now().plus(duration)));res.addHeader("Set-Cookie",ResponseCookie.from(cookieName(),token).httpOnly(true).secure(config.secureCookies()).sameSite("Lax").path("/").maxAge(duration).build().toString());}
 @Transactional public Map<String,Object> login(UUID id,HttpServletRequest req,HttpServletResponse res){var old=session(req);if(old!=null)db.jdbc.update("DELETE FROM auth_session WHERE id=?",uuid(old,"id"));String csrf=Crypto.token();var u=db.one("SELECT * FROM app_user WHERE id=? AND active=true",id);create(id,csrf,res,str(u,"kind").equals("STAFF")?Duration.ofHours(12):Duration.ofDays(1));return Map.of("userId",id,"kind",str(u,"kind"),"roles",db.jdbc.queryForList("SELECT role FROM staff_role WHERE user_id=?",String.class,id),"csrfToken",csrf);}
 @Transactional public Map<String,Object> guest(HttpServletRequest req,HttpServletResponse res){var s=session(req);if(s!=null&&s.get("user_id")!=null)return login(uuid(s,"user_id"),req,res);UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO app_user(id,kind) VALUES(?,'GUEST')",id);return login(id,req,res);}
 @Transactional public Map<String,Object> staffLogin(String username,String password,String totp,HttpServletRequest req,HttpServletResponse res){var users=db.jdbc.queryForList("SELECT * FROM app_user WHERE username=? AND kind='STAFF' AND active=true",username);if(users.isEmpty()||!passwords.matches(password,str(users.get(0),"password_hash")))throw new Problem(401,"INVALID_LOGIN","ชื่อผู้ใช้หรือข้อมูลยืนยันไม่ถูกต้อง");var u=users.get(0);String secret=str(u,"totp_secret_ciphertext");if(!secret.equals("LOCAL_MFA_DISABLED")&&!Crypto.totp(crypto.decrypt(secret),totp))throw new Problem(401,"INVALID_LOGIN","ชื่อผู้ใช้หรือข้อมูลยืนยันไม่ถูกต้อง");if(secret.equals("LOCAL_MFA_DISABLED")&&!config.local())throw new Problem(403,"MFA_REQUIRED","ต้องเปิด MFA ก่อนใช้งาน");return login(uuid(u,"id"),req,res);}
 @Transactional public Map<String,Object> lineLogin(String idToken,HttpServletRequest req,HttpServletResponse res){if(config.lineLoginChannelId().isBlank())throw Problem.bad("ยังไม่ได้ตั้งค่า LINE Login");Map<?,?> verified;try{var form=new org.springframework.util.LinkedMultiValueMap<String,String>();form.add("id_token",idToken);form.add("client_id",config.lineLoginChannelId());verified=RestClient.create().post().uri("https://api.line.me/oauth2/v2.1/verify").contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(Map.class);}catch(RuntimeException e){throw new Problem(401,"INVALID_LINE_TOKEN","ยืนยันบัญชี LINE ไม่สำเร็จ");}if(verified==null||!config.lineLoginChannelId().equals(String.valueOf(verified.get("aud")))||!"https://access.line.me".equals(verified.get("iss"))||Long.parseLong(String.valueOf(verified.get("exp")))<=Instant.now().getEpochSecond())throw new Problem(401,"INVALID_LINE_TOKEN","บัญชี LINE หมดอายุ");String subject=String.valueOf(verified.get("sub"));var found=db.jdbc.queryForList("SELECT id FROM app_user WHERE line_subject=?",subject);var old=session(req);UUID guest=old!=null&&old.get("user_id")!=null?uuid(old,"user_id"):null;UUID id=found.isEmpty()?UUID.randomUUID():uuid(found.get(0),"id");if(found.isEmpty()){db.jdbc.update("INSERT INTO app_user(id,kind,line_subject,display_name) VALUES(?,'CUSTOMER',?,?)",id,subject,String.valueOf(verified.getOrDefault("name",null)));}if(guest!=null&&!guest.equals(id)&&"GUEST".equals(str(db.one("SELECT kind FROM app_user WHERE id=?",guest),"kind"))){db.jdbc.update("UPDATE orders SET customer_id=? WHERE customer_id=?",id,guest);db.jdbc.update("UPDATE quote SET customer_id=? WHERE customer_id=?",id,guest);db.jdbc.update("INSERT INTO table_visit_member(visit_id,user_id) SELECT visit_id,? FROM table_visit_member WHERE user_id=? ON CONFLICT DO NOTHING",id,guest);db.jdbc.update("DELETE FROM auth_session WHERE user_id=?",guest);}return login(id,req,res);}
 @Transactional public void logout(HttpServletRequest req,HttpServletResponse res){var s=session(req);if(s!=null)db.jdbc.update("DELETE FROM auth_session WHERE id=?",uuid(s,"id"));res.addHeader("Set-Cookie",ResponseCookie.from(cookieName(),"").httpOnly(true).secure(config.secureCookies()).sameSite("Lax").path("/").maxAge(0).build().toString());}
}
